use crate::error::AppError;

pub fn opt_number(value: Option<i64>) -> String {
    value.map(|number| number.to_string()).unwrap_or_default()
}

pub fn opt_text(value: Option<String>) -> String {
    value.unwrap_or_default().trim().to_string()
}

/// Slugs are generated by `safeSlug` in the agent as `[a-z0-9-]`, max 80 chars.
/// Anything else cannot name a real edition and is rejected instead of being
/// interpolated into the request path.
pub fn require_slug(raw: &str) -> Result<String, AppError> {
    let trimmed = raw.trim();
    let valid = !trimmed.is_empty()
        && trimmed.len() <= 80
        && trimmed
            .chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-');
    if !valid {
        return Err(AppError::Config(format!(
            "slug de edição inválido: {trimmed}"
        )));
    }
    Ok(trimmed.to_string())
}

/// Modes are matched against the API's own list; the console never invents one.
pub fn require_mode(raw: &str) -> Result<String, AppError> {
    let mode = raw.trim().to_ascii_uppercase();
    if mode.is_empty() || mode.len() > 32 || !mode.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        return Err(AppError::Config(format!("modo de execução inválido: {raw}")));
    }
    Ok(mode)
}

